using System.Diagnostics;using SchoolERP.Api.Logging;using SchoolERP.Shared.Models;namespace SchoolERP.Api.ErrorHandling;public static class ApiErrorWriter{public static ApiErrorResponse Create(HttpContext c,string code,string message,int status,IDictionary<string,string[]>? errors=null)=>ApiErrorResponse.Create(code,message,status,c.Items[CorrelationIdMiddleware.ItemKey]?.ToString(),errors,Activity.Current?.TraceId.ToString());public static Task WriteAsync(HttpContext c,ApiErrorResponse error,CancellationToken ct=default){c.Response.StatusCode=error.Status;c.Response.ContentType="application/json; charset=utf-8";return c.Response.WriteAsJsonAsync(error,ct);}}
